INSERT INTO `knowledge_articles` (`title`, `category`, `body`, `minimum_role`, `published`, `author_email`) VALUES
('1. Путівник INCORA People: старт', 'Путівник INCORA People', '1.1 Призначення системи\nINCORA People — внутрішній простір для людей, часу, відсутностей, документів та операцій компанії.\n\n1.1.1 Головне меню\nГоловна показує персональні задачі й новини. Люди містить директорію. Відпустки — відсутності. Час — робочий час.\n\n1.1.2 Профіль і мова\nВідкрийте меню профілю внизу ліворуч, щоб перейти до особистих налаштувань і змінити мову між українською та англійською.\n\n1.1.3 Пошук і режим роботи\nНатисніть Ctrl/Cmd + K або поле пошуку зверху, щоб знайти працівника. У верхній панелі перемикайте статус: в офісі або віддалено.', 'employee', 1, 'system@incora.people'),
('2. Робота працівника: профіль, новини й задачі', 'Путівник INCORA People', '2.1 Люди\nВідкрийте профіль колеги для ролі, команди й контактів. Кнопка Google Chat відкриває пошук діалогу за корпоративною адресою.\n\n2.1.1 Оголошення\nТут зібрані опубліковані компанією оновлення; закріплені повідомлення завжди зверху.\n\n2.1.2 Завдання\nВиконуйте персональні, онбординг- і офбординг-задачі. Позначайте завершені лише після фактичного виконання.\n\n2.1.3 Відшкодування\nВідшкодування доступні з особистого профілю. Додайте заявку лише у дозволеній категорії та прикріпіть підтвердний документ.', 'employee', 1, 'system@incora.people'),
('3. Відсутності та календар', 'Путівник INCORA People', '3.1 Баланси\nУ Відпустках видно доступні дні за кожним типом відсутності.\n\n3.1.1 Нова заявка\nОберіть тип, дати та коментар. Система рахує робочі дні й передає заявку на погодження.\n\n3.1.2 Календар\nКалендар показує затверджені відсутності та корпоративні свята. Не створюйте дубль заявок: перевірте календар команди перед плануванням.', 'employee', 1, 'system@incora.people'),
('4. Час: табель, коди часу та виправлення', 'Путівник INCORA People', '4.1 Трекер\nЗапустіть таймер із верхньої панелі з будь-якої сторінки або з модуля Час. Не забудьте зупинити його наприкінці дня.\n\n4.1.1 Ручний запис\nДодайте інтервал, проєкт і код часу: проєктна, внутрішня, навчання або адміністративна робота. Не створюйте записи, що перетинаються.\n\n4.1.2 Виправлення\nЯкщо час неправильний, подайте запит на виправлення з поясненням. Не редагуйте затверджений період — попросіть менеджера відкрити його.', 'employee', 1, 'system@incora.people'),
('5. Активи, документи й база знань', 'Путівник INCORA People', '5.1 Активи\nПереглядайте видані вам активи. Стани: доступний, виданий, у ремонті, списаний. Якщо стан або власник не відповідають реальності, зверніться до HR.\n\n5.1.1 Документи\nТут публікуються політики, шаблони та корпоративні файли. Відкривайте файли лише через застосунок.\n\n5.1.2 База знань\nВикористовуйте пошук і категорії. Частина статей може бути недоступною — це означає, що вона призначена для іншої ролі.', 'employee', 1, 'system@incora.people'),
('6. Менеджер: погодження команди', 'Путівник INCORA People', '6.1 Відпустки й час\nМенеджер бачить заявки прямої команди та може погодити або відхилити їх із коментарем.\n\n6.1.1 Табелі команди\nЗвіряйте факт, норму, понаднормові й аномалії. Перед погодженням переконайтеся, що немає активного таймера або незакритих запитів на виправлення.\n\n6.1.2 Рішення за періодом\nПогодити блокує погоджений період. Повернути повертає його працівнику з обов’язковим коментарем. Експорт завантажує CSV команди.', 'manager', 1, 'system@incora.people'),
('7. HR: адміністрування людей і контенту', 'Путівник INCORA People', '7.1 Люди й організація\nHR керує профілями, імпортом CSV, оргструктурою, менеджерами, документами та балансами.\n\n7.1.1 Політики\nУ Налаштуваннях налаштовуються типи відсутностей, правила відшкодувань, ролі й доступи. Зміни політик впливають на всю компанію — перевіряйте їх перед збереженням.\n\n7.1.2 Активи й база знань\nВидавайте та повертайте активи тільки після фактичної передачі. Історія рухів зберігається. Для статей задавайте мінімальну роль: працівник, менеджер, HR або суперадміністратор.', 'hr_admin', 1, 'system@incora.people'),
('8. Суперадміністратор: контроль і підтримка', 'Путівник INCORA People', '8.1 Повний доступ\nСуперадміністратор має всі можливості HR і доступ до системного контролю.\n\n8.1.1 Журнал аудиту\nВикористовуйте журнал аудиту для перевірки важливих дій. Не редагуйте дані лише за журналом — спочатку перевірте контекст операції.\n\n8.1.2 Баг-тікети\nПереглядайте повідомлення про помилки, відкривайте скріншот, перевіряйте проблему та позначайте тікет виконаним лише після фактичної перевірки виправлення.', 'super_admin', 1, 'system@incora.people');
